(44925, 'Numbers 32:38', 'Numbers', 32, 38, 'سبمه او هغه ښارونه چې د نبو او بعل معون په نوم پېژندل کېدل، بیا ودان کړل. دوی په هغو ټولو ښارونو باندې نوي نومونه کېښودل.', 'سبمه او هغه شارونه چې د نبو او بعل معون په نوم پېژندل کېدل، بیا ودان کرل. دوی په هغو تولو شارونو باندې نوی نومونه کېشودل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_32_38.mp3', 'https://drive.google.com/file/d/1vJoxP2lyi_FKkqRkEBQA5YqRSkFeRfG2/preview', 1761237843, 1761237843),
(44926, 'Numbers 32:39', 'Numbers', 32, 39, 'د منسي د زوی ماخیر طایفې د جلعاد په خاوره باندې حمله وکړه او هغه یې ونیوله او اموریان یې د هغه ځای نه وشړل.', 'د منسی د زوی ماخیر طایفې د جلعاد په خاوره باندې حمله وکره او هغه یې ونیوله او اموریان یې د هغه جای نه وشرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_32_39.mp3', 'https://drive.google.com/file/d/1DhvVpJY_9I3BhnY-HJ6xVXkXni0mGCRV/preview', 1761237843, 1761237843),
(44927, 'Numbers 32:40', 'Numbers', 32, 40, 'نو موسی د جلعاد سیمه د ماخیر طایفې ته ورکړه او هغوی په کې اوسېدل.', 'نو موسی د جلعاد سیمه د ماخیر طایفې ته ورکره او هغوی په کې اوسېدل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_32_40.mp3', 'https://drive.google.com/file/d/1sl8w509GJueHp6UAo_8blZ4NjcaOA8sn/preview', 1761237843, 1761237843),
(44928, 'Numbers 32:41', 'Numbers', 32, 41, 'یاییر چې د منسي د قبیلې څخه ؤ، حمله وکړه او څو کلي یې ونیول او په هغو باندې یې دا نوم کېښود «د یاییر کلي.»', 'یاییر چې د منسی د قبیلې چخه و، حمله وکره او چو کلی یې ونیول او په هغو باندې یې دا نوم کېشود «د یاییر کلی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_32_41.mp3', 'https://drive.google.com/file/d/1SOzqXM_LQIqg2h87a7gzIp60BSVqOv_s/preview', 1761237843, 1761237843),
(44929, 'Numbers 32:42', 'Numbers', 32, 42, 'نوبح د قنات ښار د هغه د کلیو سره ونیوه او هغه یې د خپل ځان یعنې نوبح په نوم یاد کړ.', 'نوبح د قنات شار د هغه د کلیو سره ونیوه او هغه یې د خپل جان یعنې نوبح په نوم یاد کر.', 'OT', 'afghan2023', 'afghan', '', '', 1761237843, 1761237843),
(44930, 'Joshua 18:1', 'Joshua', 18, 1, 'کله چې هغوی هغه خاوره ونیوله، د اسراییلو ټول قوم په شیلوه کې سره راټول شو او هلته یې سپېڅلې خېمه ودروله.', 'کله چې هغوی هغه خاوره ونیوله، د اسراییلو تول قوم په شیلوه کې سره راتول شو او هلته یې سپېچلې خېمه ودروله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44931, 'Joshua 18:2', 'Joshua', 18, 2, 'خو د اسراییلو اووه قبیلې وې چې خپله د ځمکې برخه لا ورته نه وه ورکړل شوې.', 'خو د اسراییلو اووه قبیلې وې چې خپله د جمکې برخه لا ورته نه وه ورکرل شوې.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44932, 'Joshua 18:3', 'Joshua', 18, 3, 'نو یوشع د اسراییلو قوم ته وویل: «تاسو به ترڅو پورې د هغې ځمکې په نیولو کې چې ستاسو د نیکونو څښتن خدای تاسو ته درکړې ده سستي کوئ؟', 'نو یوشع د اسراییلو قوم ته وویل: «تاسو به ترچو پورې د هغې جمکې په نیولو کې چې ستاسو د نیکونو چشتن خدای تاسو ته درکرې ده سستی کوی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44933, 'Joshua 18:4', 'Joshua', 18, 4, 'د هرې قبیلې څخه درې درې تنه وټاکئ. زه به هغوی ولېږم چې ټول هېواد وګوري او هغه سیمه اندازه کړي چې هغوی به یې د خپل ملکیت په توګه تر لاسه کوي. بیا دې هغوی بېرته ماته راشي.', 'د هرې قبیلې چخه درې درې تنه وتاکی. زه به هغوی ولېزم چې تول هېواد وګوری او هغه سیمه اندازه کری چې هغوی به یې د خپل ملکیت په توګه تر لاسه کوی. بیا دې هغوی بېرته ماته راشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44934, 'Joshua 18:5', 'Joshua', 18, 5, 'د هغوی په منځ کې به دا ځمکه په اوو برخو ووېشل شي. د یهودا قبیله به په خپله سیمه یعنې په جنوب کې پاتې شي او د یوسف اولاده به په خپله سیمه یعنې شمال کې پاتې شي.', 'د هغوی په منج کې به دا جمکه په اوو برخو ووېشل شی. د یهودا قبیله به په خپله سیمه یعنې په جنوب کې پاتې شی او د یوسف اولاده به په خپله سیمه یعنې شمال کې پاتې شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44935, 'Joshua 18:6', 'Joshua', 18, 6, 'وروسته له هغې چې تاسو د ځمکې د اوو برخو تشریح ولیکئ، ماته یې دلته راوړئ او زه به د خپل څښتن خدای په حضور کې ستاسو دپاره پچه واچوم.', 'وروسته له هغې چې تاسو د جمکې د اوو برخو تشریح ولیکی، ماته یې دلته راوری او زه به د خپل چشتن خدای په حضور کې ستاسو دپاره پچه واچوم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44936, 'Joshua 18:7', 'Joshua', 18, 7, 'خو بیاهم لاویان به ستاسو د پاتې خلکو سره د ځمکې برخه تر لاسه نه کړي، ځکه چې د هغوی برخه څښتن ته د کاهنانو په توګه خدمت کول دي. بې له شکه د جاد، روبین او د ختیځې منسي قبیلو لا مخکې د اردن د سیند په ختیځ کې خپله ځمکه تر لاسه کړې ده، هغه ځمکه د څښتن خدمتګار یعنې موسی هغوی ته ورکړې ده.»', 'خو بیاهم لاویان به ستاسو د پاتې خلکو سره د جمکې برخه تر لاسه نه کری، جکه چې د هغوی برخه چشتن ته د کاهنانو په توګه خدمت کول دی. بې له شکه د جاد، روبین او د ختیجې منسی قبیلو لا مخکې د اردن د سیند په ختیج کې خپله جمکه تر لاسه کرې ده، هغه جمکه د چشتن خدمتګار یعنې موسی هغوی ته ورکرې ده.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44937, 'Joshua 18:8', 'Joshua', 18, 8, 'څنګه چې هغه کسان د هغې ځمکې د نقشې اخیستلو دپاره روان شول، نو یوشع هغوی ته وویل: «لاړ شئ او د ټولې خاورې اندازه واخلئ او د هغه بیان ولیکئ. بیا ماته راشئ او زه به دلته په شیلوه کې د څښتن په حضور کې ستاسو دپاره پچه واچوم.»', 'چنګه چې هغه کسان د هغې جمکې د نقشې اخیستلو دپاره روان شول، نو یوشع هغوی ته وویل: «لار شی او د تولې خاورې اندازه واخلی او د هغه بیان ولیکی. بیا ماته راشی او زه به دلته په شیلوه کې د چشتن په حضور کې ستاسو دپاره پچه واچوم.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44938, 'Joshua 18:9', 'Joshua', 18, 9, 'هغه کسان لاړل او په ټول هېواد کې وګرځېدل او دا یې ولیکل چې هغوی څنګه هغه ځمکه په اوو برخو ووېشله او د ښارګوټو لست یې جوړ کړ. بیا هغوی بېرته یوشع ته چې د شیلوه په کمپ کې ؤ راستانه شول.', 'هغه کسان لارل او په تول هېواد کې وګرجېدل او دا یې ولیکل چې هغوی چنګه هغه جمکه په اوو برخو ووېشله او د شارګوتو لست یې جور کر. بیا هغوی بېرته یوشع ته چې د شیلوه په کمپ کې و راستانه شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44939, 'Joshua 18:10', 'Joshua', 18, 10, 'بیا یوشع د هغوی دپاره په شیلوه کې د څښتن په حضور کې پچه واچوله او د اسراییلو هرې پاتې قبیلې ته یې د ځمکې یوه ټاکلې برخه ورکړه.', 'بیا یوشع د هغوی دپاره په شیلوه کې د چشتن په حضور کې پچه واچوله او د اسراییلو هرې پاتې قبیلې ته یې د جمکې یوه تاکلې برخه ورکره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44940, 'Joshua 18:11', 'Joshua', 18, 11, 'لومړنۍ قبیله چې د پچې له مخې یې ځمکه تر لاسه کړه هغه د بنیامین قبیله وه. د هغوی د طایفو ځمکه د یهودا او یوسف د قبیلو ترمنځ پرته وه.', 'لومرنی قبیله چې د پچې له مخې یې جمکه تر لاسه کره هغه د بنیامین قبیله وه. د هغوی د طایفو جمکه د یهودا او یوسف د قبیلو ترمنج پرته وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44941, 'Joshua 18:12', 'Joshua', 18, 12, 'په شمال کې د هغوی سرحد د اردن د سیند څخه پیل شوی دی او بیا د اریحا په شمالي مخ ځوړي باندې پورته تللی او په لوېدیځ کې د غرنۍ سیمې په لاره بیت آون ته نژدې دښتې ته رسېدلی دی.', 'په شمال کې د هغوی سرحد د اردن د سیند چخه پیل شوی دی او بیا د اریحا په شمالی مخ جوری باندې پورته تللی او په لوېدیج کې د غرنی سیمې په لاره بیت اون ته نژدې دشتې ته رسېدلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44942, 'Joshua 18:13', 'Joshua', 18, 13, 'بیا دا سرحد هغه مخ ځوړي ته چې د لوز (چې بیت ییل هم بلل کیږي) جنوب خواته دی تللی دی. بیا هغه عطاروت ادار ته چې د ښکتني بیت حورون په جنوب کې په غره باندې ؤ، رسېدلی دی.', 'بیا دا سرحد هغه مخ جوری ته چې د لوز (چې بیت ییل هم بلل کیزی) جنوب خواته دی تللی دی. بیا هغه عطاروت ادار ته چې د شکتنی بیت حورون په جنوب کې په غره باندې و، رسېدلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_13.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44943, 'Joshua 18:14', 'Joshua', 18, 14, 'بیا دا سرحد بلې خواته تللی، د دې غره د لوېدیځې خوا څخه جنوب ته ګرځېدلی او قریت بعل (قریت یعاریم) ته وتلی دی. هغه ځای د یهودا د قبیلې دی. دا لوېدیځ سرحد ؤ.', 'بیا دا سرحد بلې خواته تللی، د دې غره د لوېدیجې خوا چخه جنوب ته ګرجېدلی او قریت بعل (قریت یعاریم) ته وتلی دی. هغه جای د یهودا د قبیلې دی. دا لوېدیج سرحد و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44944, 'Joshua 18:15', 'Joshua', 18, 15, 'جنوبي سرحد د قریت یعاریم د غاړې څخه شروع شوی او د نفتوح چینو ته رسېدلی دی.', 'جنوبی سرحد د قریت یعاریم د غارې چخه شروع شوی او د نفتوح چینو ته رسېدلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44945, 'Joshua 18:16', 'Joshua', 18, 16, 'بیا دا سرحد د غره بېخ ته چې د هنوم د زوی درې ته مخامخ دی او د رفاییم د درې په شمال کې دی ښکته شوی دی. د هغه ځای څخه جنوب خواته د هنوم د درې له لارې هغې غونډۍ ته چې د اورشلیم په جنوب کې ده تللی او بیا عین روجل ته رسېدلی دی.', 'بیا دا سرحد د غره بېخ ته چې د هنوم د زوی درې ته مخامخ دی او د رفاییم د درې په شمال کې دی شکته شوی دی. د هغه جای چخه جنوب خواته د هنوم د درې له لارې هغې غوندی ته چې د اورشلیم په جنوب کې ده تللی او بیا عین روجل ته رسېدلی دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
(44946, 'Joshua 18:17', 'Joshua', 18, 17, 'بیا د شمال خواته عین شمس ته ګرځېدلی او بیا د جلیلوت خواته چې د ادومیم غاښي ته مخامخ ؤ، وتلی دی. دا سرحد بیا د بوهن ګټ ته ښکته شوی دی (بوهن د روبین زوی ؤ)', 'بیا د شمال خواته عین شمس ته ګرجېدلی او بیا د جلیلوت خواته چې د ادومیم غاشی ته مخامخ و، وتلی دی. دا سرحد بیا د بوهن ګت ته شکته شوی دی (بوهن د روبین زوی و)', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44947, 'Joshua 18:18', 'Joshua', 18, 18, 'او د هغې غونډۍ شمال خواته تېر شوی چې د اردن دره ورڅخه ښکاري. بیا دا سرحد درې ته ښکته شوی دی،', 'او د هغې غوندی شمال خواته تېر شوی چې د اردن دره ورچخه شکاری. بیا دا سرحد درې ته شکته شوی دی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44948, 'Joshua 18:19', 'Joshua', 18, 19, 'د هغه ځای څخه د بیت حجلې د غونډۍ د شمالي خوا څخه تېر شوی او د مړې بحیرې په شمال کې چې د اردن سیند ورسره یوځای کیږي ختم شوی دی. دا جنوبي سرحد ؤ.', 'د هغه جای چخه د بیت حجلې د غوندی د شمالی خوا چخه تېر شوی او د مرې بحیرې په شمال کې چې د اردن سیند ورسره یوجای کیزی ختم شوی دی. دا جنوبی سرحد و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_19.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237843, 1761237843),
(44949, 'Joshua 18:20', 'Joshua', 18, 20, 'د اردن سیند ختیځ سرحد ؤ. دا د هغې خاورې سرحدونه وو چې د بنیامین د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کړې وه.', 'د اردن سیند ختیج سرحد و. دا د هغې خاورې سرحدونه وو چې د بنیامین د قبیلې طایفو د خپل ملکیت په توګه تر لاسه کرې وه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_18_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237843, 1761237843),
